"""Shared primitives for the CrossCheck replay contract.

The module keeps the historical ``NetworkTopology`` helper alive (the package
convention for counter names is part of the wire contract) and adds the
deterministic integer primitives used by the replay engine:

* :class:`NetworkTopology` -- immutable view over a topology document,
* :func:`agreement_band`    -- the closed-interval agreement band selection,
* :func:`compute_predictions` -- routed demand predictions,
* :func:`is_integer`        -- strict integer predicate (booleans are not
  integers anywhere in this schema).
"""

from bisect import bisect_left
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

# Parts per million scale used by epsilon/bias/tau and by the agreement band.
PPM = 1000000
# Weight scale of a routing bundle (weights of one bundle sum to 1000).
WEIGHT_SCALE = 1000
# Largest admissible demand value.
MAX_DEMAND = 1000000000


def is_integer(value) -> bool:
    """Return True for genuine integers; booleans are never integers here."""
    return isinstance(value, int) and not isinstance(value, bool)


class NetworkTopology:
    """Immutable view over a topology document.

    Node names keep the package convention for counter keys:
    ``low_<A>_egress_to_<B>`` / ``low_<B>_ingress_from_<A>`` for internal
    directed flows and ``low_<A>_origination`` / ``low_<A>_termination`` for
    the two external interfaces of a node.
    """

    def __init__(self, document: Dict):
        self.nodes: Dict[int, Dict] = {}
        self.names: Dict[int, str] = {}
        for node in document.get("nodes") or []:
            node_id = node["id"]
            self.nodes[node_id] = node
            self.names[node_id] = node["name"]
        self.name_to_id: Dict[str, int] = {name: nid for nid, name in self.names.items()}

        self.links: List[Tuple[int, int, int]] = []
        self.link_capacity: Dict[Tuple[int, int], int] = {}
        for link in document.get("links") or []:
            source = link["source"]
            target = link["target"]
            capacity = link["capacity"]
            self.links.append((source, target, capacity))
            self.link_capacity[(source, target)] = capacity
            self.link_capacity[(target, source)] = capacity

        self.external_names: List[str] = list(document.get("external_nodes") or [])
        self.external_ids: List[int] = [self.name_to_id[name] for name in self.external_names]
        self.external_id_set = set(self.external_ids)

        # Directed flows in canonical order (ascending integer pair).
        flows = set()
        for source, target, _cap in self.links:
            flows.add((source, target))
            flows.add((target, source))
        for node_id in self.external_ids:
            flows.add((-1, node_id))
            flows.add((node_id, -1))
        self.flows: List[Tuple[int, int]] = sorted(flows)
        self.flow_index: Dict[Tuple[int, int], int] = {
            flow: index for index, flow in enumerate(self.flows)
        }

        # Capacity bound of every directed flow.
        self.flow_capacity: Dict[Tuple[int, int], int] = {}
        for flow in self.flows:
            source, target = flow
            if source == -1:
                self.flow_capacity[flow] = int(self.nodes[target].get("external_capacity", 0))
            elif target == -1:
                self.flow_capacity[flow] = int(self.nodes[source].get("external_capacity", 0))
            else:
                self.flow_capacity[flow] = int(self.link_capacity[flow])

        # Counter keys and their orientation.
        self.flow_report_keys: Dict[Tuple[int, int], Tuple[Optional[str], Optional[str]]] = {}
        self.counter_flow: Dict[str, Tuple[int, int]] = {}
        for flow in self.flows:
            source, target = flow
            if source == -1:
                reports = (None, "low_%s_origination" % self.names[target])
            elif target == -1:
                reports = ("low_%s_termination" % self.names[source], None)
            else:
                reports = (
                    "low_%s_egress_to_%s" % (self.names[source], self.names[target]),
                    "low_%s_ingress_from_%s" % (self.names[target], self.names[source]),
                )
            self.flow_report_keys[flow] = reports
            for key in reports:
                if key is not None:
                    self.counter_flow[key] = flow
        self.counter_keys: List[str] = sorted(self.counter_flow)

        # Incident routers of every flow: (router, is_outgoing).
        self.flow_endpoints: Dict[Tuple[int, int], List[Tuple[int, bool]]] = {}
        self.router_flows: Dict[int, List[Tuple[Tuple[int, int], bool]]] = {}
        for flow in self.flows:
            source, target = flow
            endpoints = []
            if source >= 0:
                endpoints.append((source, True))
            if target >= 0:
                endpoints.append((target, False))
            self.flow_endpoints[flow] = endpoints
            for router, is_out in endpoints:
                self.router_flows.setdefault(router, []).append((flow, is_out))

    # -- helpers ---------------------------------------------------------
    def canonical(self) -> List:
        """Order independent representation of the topology."""
        nodes = sorted(
            [self.nodes[nid]["id"], self.nodes[nid]["name"], int(self.nodes[nid].get("external_capacity", 0))]
            for nid in self.nodes
        )
        links = sorted(
            [min(source, target), max(source, target), cap] for source, target, cap in self.links
        )
        return [nodes, links, sorted(self.external_names)]

    def node_name(self, node_id: int) -> str:
        return self.names[node_id]


def agreement_band(items: Iterable[Tuple[int, int]], epsilon: int) -> Tuple[int, int]:
    """Select the winning agreement band of a weighted value multiset.

    ``items`` is an iterable of ``(value, weight)`` pairs with nonnegative
    integer values and positive integer weights.  A band is a closed interval
    ``[lo, hi]`` whose endpoints are observed values and that satisfies
    ``1000000 * (hi - lo) <= epsilon * hi``.  The winning band has the greatest
    total weight, then the smallest ``lo``, then the smallest ``hi``.  Its
    representative is the floor of its weighted mean and its mass is its total
    weight.
    """
    aggregated: Dict[int, int] = {}
    for value, weight in items:
        aggregated[value] = aggregated.get(value, 0) + weight
    if not aggregated:
        return 0, 0
    values = sorted(aggregated)
    count = len(values)
    weight_prefix = [0] * (count + 1)
    mean_prefix = [0] * (count + 1)
    for index, value in enumerate(values):
        weight = aggregated[value]
        weight_prefix[index + 1] = weight_prefix[index] + weight
        mean_prefix[index + 1] = mean_prefix[index] + value * weight

    best_key = None
    best_rep = 0
    best_mass = 0
    for upper in range(count):
        high = values[upper]
        # 1000000 * (high - low) <= epsilon * high
        #   <=>  low >= ceil(high * (1000000 - epsilon) / 1000000)
        threshold = (high * (PPM - epsilon) + PPM - 1) // PPM
        lower = bisect_left(values, threshold, 0, upper + 1)
        if lower > upper:
            lower = upper
        low = values[lower]
        mass = weight_prefix[upper + 1] - weight_prefix[lower]
        key = (-mass, low, high)
        if best_key is None or key < best_key:
            total = mean_prefix[upper + 1] - mean_prefix[lower]
            best_key = key
            best_rep = total // mass
            best_mass = mass
    return best_rep, best_mass


def compute_predictions(
    topology: NetworkTopology,
    demands: Dict[Tuple[int, int], int],
    routes: Optional[Dict[Tuple[int, int], List[Tuple[Tuple[int, ...], int]]]],
) -> Dict[Tuple[int, int], int]:
    """Predicted load of every directed flow.

    Internal flows use the routed demand model (``floor`` after all
    contributions), external flows use their full demand marginal.  The result
    is never rounded or clamped beyond the documented floor.
    """
    predictions: Dict[Tuple[int, int], int] = {}
    if routes is not None:
        accumulated: Dict[Tuple[int, int], int] = {}
        for (source, target), demand in demands.items():
            if demand <= 0:
                continue
            bundle = routes.get((source, target))
            if not bundle:
                continue
            for path, weight in bundle:
                for index in range(len(path) - 1):
                    hop = (path[index], path[index + 1])
                    accumulated[hop] = accumulated.get(hop, 0) + demand * weight
        for flow in topology.flows:
            source, target = flow
            if source == -1 or target == -1:
                continue
            predictions[flow] = accumulated.get(flow, 0) // WEIGHT_SCALE

    outgoing: Dict[int, int] = {}
    incoming: Dict[int, int] = {}
    for (source, target), demand in demands.items():
        outgoing[source] = outgoing.get(source, 0) + demand
        incoming[target] = incoming.get(target, 0) + demand
    for node_id in topology.external_ids:
        predictions[(-1, node_id)] = outgoing.get(node_id, 0)
        predictions[(node_id, -1)] = incoming.get(node_id, 0)
    return predictions
